/**
 * Record Page — /record
 *
 * A simple audio-recording interface. The user taps a central record button
 * to start/stop recording. While recording, a pulsing ring and elapsed timer
 * provide visual feedback.
 *
 * State:
 *   - isRecording: whether a recording session is active
 *   - elapsed:     seconds elapsed since recording started
 *
 * No parent/child component dependencies — this is a standalone page.
 */
"use client";

import { useState, useRef, useEffect, useCallback } from "react";

/** Pad a number to two digits (e.g. 5 → "05"). */
function pad(n: number): string {
  return n.toString().padStart(2, "0");
}

/**
 * formatTime — converts total seconds into an "MM:SS" string.
 * @param totalSeconds  The number of seconds to format.
 * @returns             A string in "MM:SS" format.
 */
function formatTime(totalSeconds: number): string {
  const mins = Math.floor(totalSeconds / 60);
  const secs = totalSeconds % 60;
  return `${pad(mins)}:${pad(secs)}`;
}

export default function RecordPage() {
  /* ── state ─────────────────────────────────────────────── */
  const [isRecording, setIsRecording] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  /* ── timer logic ───────────────────────────────────────── */

  /** startTimer — begins a 1-second interval that increments `elapsed`. */
  const startTimer = useCallback(() => {
    setElapsed(0);
    timerRef.current = setInterval(() => {
      setElapsed((prev) => prev + 1);
    }, 1000);
  }, []);

  /** stopTimer — clears the running interval. */
  const stopTimer = useCallback(() => {
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  /* Clean up on unmount */
  useEffect(() => {
    return () => stopTimer();
  }, [stopTimer]);

  /* ── handlers ──────────────────────────────────────────── */

  /**
   * toggleRecording — flips the recording state and starts/stops the timer.
   * This is where you'd hook up the MediaRecorder API in a future iteration.
   */
  const toggleRecording = () => {
    if (isRecording) {
      stopTimer();
      setIsRecording(false);
    } else {
      startTimer();
      setIsRecording(true);
    }
  };

  /* ── render ────────────────────────────────────────────── */
  return (
    <div className="flex min-h-screen flex-col items-center justify-center gap-10 bg-background">
      {/* Elapsed timer */}
      <span className="font-mono text-5xl font-light tracking-widest text-foreground/80">
        {formatTime(elapsed)}
      </span>

      {/* Record button + pulsing ring */}
      <div className="relative flex items-center justify-center">
        {/* Pulse ring — only visible while recording */}
        {isRecording && (
          <span className="absolute h-32 w-32 animate-ping rounded-full bg-red-500/30" />
        )}

        <button
          onClick={toggleRecording}
          aria-label={isRecording ? "Stop recording" : "Start recording"}
          className={`
            relative z-10 flex h-24 w-24 items-center justify-center
            rounded-full shadow-lg transition-all duration-300
            focus:outline-none focus-visible:ring-4 focus-visible:ring-red-400/50
            ${
              isRecording
                ? "bg-red-600 hover:bg-red-700 scale-110"
                : "bg-red-500 hover:bg-red-600"
            }
          `}
        >
          {/* Icon: circle when idle, square (stop) when recording */}
          <span
            className={`
              block bg-white transition-all duration-300
              ${
                isRecording
                  ? "h-7 w-7 rounded-sm"
                  : "h-10 w-10 rounded-full"
              }
            `}
          />
        </button>
      </div>

      {/* Status label */}
      <p className="text-sm font-medium uppercase tracking-widest text-foreground/50">
        {isRecording ? "Recording…" : "Tap to record"}
      </p>
    </div>
  );
}
